package dustin.cex.domains.kyc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.edd.*;
import dustin.cex.domains.auth.model.entity.*;
import dustin.cex.domains.cdd.CustomerDeclaration;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.web.server.ResponseStatusException;

/** 현재 주의 목록·과거 이력·원문 목적 제한과 빈 필터 페이지의 진행을 검증한다. */
class CustomerReviewAttentionIntegrationTest extends CustomerFinalTestSupport {
    CustomerReviewSupervisionService.Cursor beginning;
    @BeforeEach void cursor(){var rows=jdbc.queryForList("SELECT id,created_at FROM customer_exit_review_requests WHERE id<>? ORDER BY created_at DESC,id DESC LIMIT 1",receipt.id());beginning=rows.isEmpty()?null:new CustomerReviewSupervisionService.Cursor(((Timestamp)rows.getFirst().get("created_at")).toInstant(),(UUID)rows.getFirst().get("id"));}
    CustomerReviewSupervisionService.Page attention(){return supervision.attention(independent.user().getId(),independent.sid(),beginning);}
    @Test void timelyStatusResponseIsNotFinalButNeedsNoImmediateAttention(){assertTrue(attention().items().isEmpty());var all=supervision.queue(independent.user().getId(),independent.sid(),beginning).items().getFirst();assertNull(all.finalReviewId());assertEquals(CustomerReviewResponseTarget.State.RESPONDED_ON_TIME,all.responseTarget().state());}
    @Test void approvedButUnacknowledgedAnswerIsVisibleWithoutPrivateText() throws Exception {var r=approvedFinal();var i=attention().items().getFirst();assertEquals(r.payload().id(),i.finalReviewId());assertNull(i.customerAcknowledgedAt());String raw=json.writeValueAsString(attention());for(String secret:List.of(explanation().text(),"비공개 처리 기록","reasonMac","payloadHash"))assertFalse(raw.contains(secret));assertThrows(ResponseStatusException.class,()->requests.inspect(independent.user().getId(),independent.sid(),receipt.id()));}
    @Test void explicitCustomerAckRemovesAttentionButKeepsFullHistory() throws Exception {var r=approvedFinal();finals.acknowledge(customer.getId(),sid,receipt.id(),r.payload().id(),UUID.randomUUID());assertTrue(attention().items().isEmpty());assertNotNull(supervision.queue(independent.user().getId(),independent.sid(),beginning).items().getFirst().customerAcknowledgedAt());assertEquals(1,active());}
    @Test void orphanedUnfinishedWorkNeedsAttentionEvenAfterTimelyResponse(){disable(maker);disable(checker);assertTrue(attention().items().getFirst().orphaned());assertTrue(attention().items().getFirst().requiresAttention());}
    @Test void transferredWorkUsesCurrentPeopleAndPreservesResponseTarget() throws Exception {var before=supervision.queue(independent.user().getId(),independent.sid(),beginning).items().getFirst().responseTarget();transfer();disable(maker);disable(checker);assertTrue(attention().items().isEmpty());var current=supervision.queue(independent.user().getId(),independent.sid(),beginning).items().getFirst();assertFalse(current.orphaned());assertEquals(before,current.responseTarget());assertTrue(current.members().stream().anyMatch(m->m.id()==nextPrimary.user().getId()));}
    @Test void rolesAndFreshSessionAreRequired(){assertThrows(ResponseStatusException.class,()->supervision.attention(maker.user().getId(),maker.sid(),beginning));assertThrows(ResponseStatusException.class,()->supervision.attention(independent.user().getId(),maker.sid(),beginning));var t=tokens.findBySessionId(independent.sid()).orElseThrow();t.setMfaVerifiedAt(LocalDateTime.now().minusMinutes(6));tokens.saveAndFlush(t);assertThrows(ResponseStatusException.class,this::attention);}
    @Test void auditFailureReturnsNoAttentionMetadata(){disable(maker);disable(checker);doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_REVIEW_ATTENTION_READ"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,this::attention);reset(audit);assertEquals(1,attention().items().size());}
    @Test void invalidCursorIsRejected(){assertThrows(ResponseStatusException.class,()->supervision.attention(independent.user().getId(),independent.sid(),new CustomerReviewSupervisionService.Cursor(Instant.now(),null)));}
    @Test void overdueAndClockReviewNeedAttentionButResolvedLateHistoryDoesNot(){Instant start=Instant.EPOCH,due=start.plusSeconds(86400);for(var state:CustomerReviewResponseTarget.State.values()){var assessment=new CustomerReviewResponseTarget.Assessment(CustomerReviewResponseTarget.POLICY,due,null,state);var i=new CustomerReviewSupervisionService.Item(UUID.randomUUID(),customer.getId(),original.payload().id(),start,null,List.of(),false,assessment,null,null,null);assertEquals(state==CustomerReviewResponseTarget.State.OVERDUE||state==CustomerReviewResponseTarget.State.TIME_REVIEW_REQUIRED,i.requiresAttention());}}
    @Test void twentySixRealRequestsAdvanceAcrossEmptyAttentionPage() throws Exception {CustomerExitReviewService.Receipt last=null;for(int n=0;n<25;n++){if(n%3==0){nextCustomer();initiated();}last=requests.submit(customer.getId(),sid,UUID.randomUUID(),new CustomerExitReviewService.Submission("주의 목록 페이지 경계 요청"));}receipt=last;requests.inspect(maker.user().getId(),maker.sid(),receipt.id());note=notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"마지막 접수의 실제 검토 기록"));approvedFinal();var first=attention();assertEquals(25,first.scanned());assertTrue(first.items().isEmpty());assertNotNull(first.next());var second=supervision.attention(independent.user().getId(),independent.sid(),first.next());assertEquals(receipt.id(),second.items().getFirst().requestId());assertNull(second.next());}
    void nextCustomer(){customer=users.saveAndFlush(User.builder().email(UUID.randomUUID()+"@test.invalid").passwordHash(hash).build());var token=tokens.saveAndFlush(RefreshToken.builder().userId(customer.getId()).tokenHash(UUID.randomUUID().toString()).expiresAt(LocalDateTime.now().plusHours(1)).build());sid=token.getSessionId();customerAccess=jwt.generateAccessToken(customer.getId(),sid);cdd.submit(customer.getId(),sid,UUID.randomUUID(),declaration(CustomerDeclaration.Pep.NO));}
    @Test void httpAttentionUsesApproverAndNoStore() throws Exception {String path="/api/admin/compliance/customer-review-attention";mvc.perform(get(path).header("Authorization","Bearer "+independent.access())).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store")));mvc.perform(get(path).header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());mvc.perform(get(path).header("Authorization","Bearer "+customerAccess)).andExpect(status().isForbidden());mvc.perform(get(path)).andExpect(status().isUnauthorized());}
}
